#!/bin/bash
# Uninstall script for Eclipse IDE for C/C++ Developers
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Eclipse IDE for C/C++ Developers..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Eclipse IDE for C/C++ Developers if running..."
pkill -f "Eclipse IDE for C/C++ Developers" 2>/dev/null || true

# Remove /Applications/Eclipse.app
echo "Removing /Applications/Eclipse.app..."
if [ -d "/Applications/Eclipse.app" ]; then
    rm -rf "/Applications/Eclipse.app" 2>/dev/null || true
elif [ -f "/Applications/Eclipse.app" ]; then
    rm -f "/Applications/Eclipse.app" 2>/dev/null || true
fi

# Remove /Applications/{'target': 'Eclipse CPP.app'}
echo "Removing /Applications/{'target': 'Eclipse CPP.app'}..."
if [ -d "/Applications/{'target': 'Eclipse CPP.app'}" ]; then
    rm -rf "/Applications/{'target': 'Eclipse CPP.app'}" 2>/dev/null || true
elif [ -f "/Applications/{'target': 'Eclipse CPP.app'}" ]; then
    rm -f "/Applications/{'target': 'Eclipse CPP.app'}" 2>/dev/null || true
fi

# Remove $HOME/.eclipse
echo "Removing $HOME/.eclipse..."
if [ -d "$HOME/.eclipse" ]; then
    rm -rf "$HOME/.eclipse" 2>/dev/null || true
elif [ -f "$HOME/.eclipse" ]; then
    rm -f "$HOME/.eclipse" 2>/dev/null || true
fi

# Remove $HOME/eclipse-workspace
echo "Removing $HOME/eclipse-workspace..."
if [ -d "$HOME/eclipse-workspace" ]; then
    rm -rf "$HOME/eclipse-workspace" 2>/dev/null || true
elif [ -f "$HOME/eclipse-workspace" ]; then
    rm -f "$HOME/eclipse-workspace" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/epp.package.cpp.plist
echo "Removing $HOME/Library/Preferences/epp.package.cpp.plist..."
if [ -d "$HOME/Library/Preferences/epp.package.cpp.plist" ]; then
    rm -rf "$HOME/Library/Preferences/epp.package.cpp.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/epp.package.cpp.plist" ]; then
    rm -f "$HOME/Library/Preferences/epp.package.cpp.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/epp.package.cpp.savedState
echo "Removing $HOME/Library/Saved Application State/epp.package.cpp.savedState..."
if [ -d "$HOME/Library/Saved Application State/epp.package.cpp.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/epp.package.cpp.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/epp.package.cpp.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/epp.package.cpp.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
